CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, username VARCHAR(255) NOT NULL, osu_user_id INT NULL, last_login_time TIMESTAMP NULL);
ALTER TABLE users ADD CONSTRAINT users_osu_user_id_unique UNIQUE (osu_user_id);
CREATE TABLE IF NOT EXISTS user_relations (from_id INT, to_id INT, kind INT NOT NULL, CONSTRAINT pk_user_relations PRIMARY KEY (from_id, to_id), CONSTRAINT fk_user_relations_from_id__id FOREIGN KEY (from_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_user_relations_to_id__id FOREIGN KEY (to_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS beatmapsets (id SERIAL PRIMARY KEY, creator_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, artist VARCHAR(255) NOT NULL, title VARCHAR(255) NOT NULL, CONSTRAINT fk_beatmapsets_creator_id__id FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS documents (id SERIAL PRIMARY KEY);
CREATE TABLE IF NOT EXISTS beatmaps (id SERIAL PRIMARY KEY, beatmapset_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, difficulty_owner_id INT NULL, artist VARCHAR(255) NOT NULL, title VARCHAR(255) NOT NULL, difficulty_name VARCHAR(255) NOT NULL, document_id INT NOT NULL, CONSTRAINT fk_beatmaps_beatmapset_id__id FOREIGN KEY (beatmapset_id) REFERENCES beatmapsets(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_beatmaps_difficulty_owner_id__id FOREIGN KEY (difficulty_owner_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_beatmaps_document_id__id FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS blobs (id uuid PRIMARY KEY, "size" INT NOT NULL);
CREATE TABLE IF NOT EXISTS document_snapshots (id SERIAL PRIMARY KEY, document_id INT NOT NULL, sequence_number BIGINT NOT NULL, summary JSON NOT NULL, CONSTRAINT fk_document_snapshots_document_id__id FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE document_snapshots ADD CONSTRAINT document_snapshots_document_id_sequence_number_unique UNIQUE (document_id, sequence_number);
CREATE TABLE IF NOT EXISTS document_blob_usages (snapshot_id INT, blob_id uuid, CONSTRAINT pk_document_blob_usages PRIMARY KEY (snapshot_id, blob_id), CONSTRAINT fk_document_blob_usages_snapshot_id__id FOREIGN KEY (snapshot_id) REFERENCES document_snapshots(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_document_blob_usages_blob_id__id FOREIGN KEY (blob_id) REFERENCES blobs(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE SEQUENCE IF NOT EXISTS users_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS beatmapsets_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS beatmaps_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS documents_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS document_snapshots_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
